    });
    expect(response.statusCode).toBe(409);
  });

  it('allows updating a booking to the same time slot it already occupies', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(200);
  });

  describe('availability', () => {
    function availability(roomIdValue: string, from: string, to: string) {
      const query = `roomId=${roomIdValue}&from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`;
      return app.inject({ method: 'GET', url: `/bookings/availability?${query}` });
    }

    it('reports the whole window as free when there are no bookings', async () => {
      const from = inHours(1);
      const to = inHours(2);
      const response = await availability(roomId, from, to);
      expect(response.statusCode).toBe(200);
      const body = response.json();
      expect(body.busy).toHaveLength(0);
      expect(body.free).toHaveLength(1);
      expect(new Date(body.free[0].startsAt).getTime()).toBe(new Date(from).getTime());
      expect(new Date(body.free[0].endsAt).getTime()).toBe(new Date(to).getTime());
    });

    it('splits the window into busy and free parts around a booking', async () => {
      const created = await book(24, 25);
      const from = inHours(23);
      const to = inHours(27);
      const response = await availability(roomId, from, to);
      const body = response.json();
      expect(body.busy).toHaveLength(1);
      expect(body.busy[0].bookingId).toBe(created.json().id);
      expect(body.free).toHaveLength(2);
    });

