      await book(24, 26);
      const from = inHours(25);
      const to = inHours(27);
      const response = await availability(roomId, from, to);
      const body = response.json();
      expect(body.busy).toHaveLength(1);
      expect(new Date(body.busy[0].startsAt).getTime()).toBe(new Date(from).getTime());
      expect(body.free).toHaveLength(1);
    });

    it('answers 404 for availability of a room that does not exist', async () => {
      const response = await availability('missing', inHours(1), inHours(2));
      expect(response.statusCode).toBe(404);
    });

    it('rejects an availability query with an instant that cannot be parsed', async () => {
      const response = await availability(roomId, 'yesterday', inHours(2));
      expect(response.statusCode).toBe(400);
    });

    it('rejects an availability query where to is not after from', async () => {
      const response = await availability(roomId, inHours(2), inHours(1));
      expect(response.statusCode).toBe(400);
    });
  });
});

